head.script:
scwin.gVar = {
    "cClass" : ""
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 : tableLayout(tbl1) 의 첫 번째 th 를 id target1 로 생성하고 class 설정
scwin.comp_init = async function () {
    // 기존 tableLayout 있으면 삭제 (th 는 table 의 하위 요소이므로 table 을 삭제 후 재생성)
    if (typeof scwin.tbl1 !== 'undefined' && scwin.tbl1) {
        scwin.tbl1.remove();
    }

    // 조건 설정
    let properties = {
        class: scwin.gVar["cClass"],
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성 : 첫 번째 th 에 id(target1) 와 class 적용 (class 는 기본 class 뒤에 병합)
    scwin.tbl1 = await $c.gcm.createBasicTableLayout('', '', 'tbl1', '', { th: 'id="target1" ' + cList });
    scwin.target1 = scwin.tbl1._sub.th;
}
